from ta5g_admin_operations import ta_admin_interface
import os


class ScfcAnalyzer(object):
    def __init__(self, test_name, root_log_path, xml):
        self.test_name = test_name
        self.root_log_path = root_log_path
        self.xml = xml

    def get_latest_scfc(self, scfc_filename, host_ip='127.0.0.1', timeout=60):
        """Gets the lastest scfc file and returns it's path."""
        latest_scfc_file_name = 'latest_scfc_file.xml' if scfc_filename is None else scfc_filename
        unique_directory = self._create_unique_directory(self.root_log_path, self.test_name)
        self._put_scfc_into_directory(latest_scfc_file_name, unique_directory, timeout)
        return self._prepare_relative_filepath(unique_directory, latest_scfc_file_name)

    def check_if_managed_object_exists(self, object_path, scfc_filepath=None, host_ip='127.0.0.1'):
        """Checks if given xpath to managed object exists in given scfc filename."""
        scfc_path = self._get_path_of_latest_scfc_if_needed(scfc_filepath, host_ip)
        self.xml.element_should_exist(scfc_path, self._prepare_object_path(object_path), host_ip)

    def check_if_managed_object_does_not_exist(self, object_path, scfc_filepath=None, host_ip='127.0.0.1'):
        """Checks if given xpath to managed object doest not exist in given scfc filename."""
        scfc_path = self._get_path_of_latest_scfc_if_needed(scfc_filepath, host_ip)
        self.xml.element_should_not_exist(scfc_path, self._prepare_object_path(object_path), host_ip)

    def _put_scfc_into_directory(self, scfc_file_name, directory_path, timeout=60):
        suffix = '.xml' if '.xml' not in scfc_file_name else ''
        scfc_file_name += suffix
        with ta_admin_interface.admin_interface() as admin_client:
            admin_client.get_current_scf_file(local_dir_path=directory_path, file_name=scfc_file_name, timeout=timeout)

    def _prepare_relative_filepath(self, folder_path, filename):
        return './%s/%s' % (os.path.relpath(folder_path), filename)

    def _create_unique_directory(self, folder_path, test_name):
        new_output_directory = '%s/%s' % (folder_path, test_name)
        if not os.path.exists(new_output_directory):
            os.mkdir(new_output_directory)
        return new_output_directory

    def _get_path_of_latest_scfc_if_needed(self, scfc_filepath, host_ip):
        if scfc_filepath is None:
            return self.get_latest_scfc(scfc_filepath, host_ip)
        return scfc_filepath

    def _prepare_object_path(self, object_path):
        return './/managedObject[@distName="%s"]' % object_path
